+        ([8, 120], 80),
+        ([8, 120], 100),
+        ([8, 120], 120),
+        ([10, 12, 200], 72),
+        ([21, 66], 55),
+        ([6, 200], 40),
+        ([7, 7, 7], 30),
+        ([2, 40, 9, 90], 50),
