  // ctrl+g stays unhandled: neither may leak its base letter.
  harness.sendText('\x18\x07'); // ctrl+x, ctrl+g
  await harness.settle(settleMs: 200);
  harness.sendText(' Z'); // a fresh word: one undo group of its own
