  final rng = Random(42);
  var checked = 0;
  for (var iter = 0; iter < 200000; iter++) {
    final n = 1 + rng.nextInt(8);
    final natural = [for (var i = 0; i < n; i++) 1 + rng.nextInt(250)];
    final budget = rng.nextInt(400);
    final caps = AnsiMarkdown.columnCaps(natural, budget);
    if (budget < n * 6) {
      assert(caps == null, 'expected null: $natural @ $budget → $caps');
      continue;
    }
    assert(caps != null, 'expected non-null: $natural @ $budget');
    final sum = caps!.fold<int>(0, (a, b) => a + b);
    assert(sum <= budget, 'OVER BUDGET: $natural @ $budget → $caps (sum=$sum)');
    for (var c = 0; c < n; c++) {
      assert(caps[c] <= natural[c], 'STRETCHED: $natural @ $budget → $caps');
      assert(caps[c] >= min(6, natural[c]), 'BELOW FLOOR: $natural @ $budget → $caps');
    }
    // determinism
    final again = AnsiMarkdown.columnCaps(natural, budget);
    assert(again.toString() == caps.toString(), 'NONDETERMINISTIC: $natural @ $budget');
    checked++;
  }
  // Targeted: fit-preservation — a column within fair share never shrinks.
  for (var iter = 0; iter < 100000; iter++) {
    final n = 2 + rng.nextInt(6);
    final natural = [for (var i = 0; i < n; i++) 1 + rng.nextInt(200)];
    final budget = n * 6 + rng.nextInt(300);
    final caps = AnsiMarkdown.columnCaps(natural, budget);
    if (caps == null) continue;
    // simulate water-filling to know which columns should have fit
    var pool = budget;
    var pending = [for (var c = 0; c < n; c++) c];
    final shouldFit = <int>{};
    while (pending.isNotEmpty) {
      final fair = pool ~/ pending.length;
      final fitted = [for (final c in pending) if (natural[c] <= fair) c];
      if (fitted.isEmpty) break;
      for (final c in fitted) { shouldFit.add(c); pool -= natural[c]; }
      pending = [for (final c in pending) if (!shouldFit.contains(c)) c];
    }
    for (final c in shouldFit) {
      assert(caps![c] == natural[c], 'FIT LOST: $natural @ $budget → $caps (col $c)');
    }
  }
  print('OK — $checked budget-paying shapes + fit-preservation checks passed');
